      mode: text("mode").default("aac_caretaker").notNull(),
      // 'aac_caretaker' | 'aac_aac' | ...
      status: text("status").default("ringing").notNull(),
      // ringing|active|ended|missed|declined|cancelled
      media: jsonb("media").default({}).notNull(),
      // requested tracks {audio,video,pose}
      game: jsonb("game"),
      // attached social game (CallGame) or null = plain video chat
