      // Whether users can manually select this persona
      active: boolean2("active").default(true).notNull(),
      testMode: boolean2("test_mode").default(false).notNull(),
      // If true, only system admins can see this persona
      instituteId: varchar2("institute_id").references(() => institutes.id),
      // If set, only users in this institute can see it
      llmProvider: text2("llm_provider"),
      // Optional per-persona LLM provider override (e.g. "openai", "gemini", "claude")
      llmModel: text2("llm_model"),
      // Optional per-persona LLM model override (e.g. "gpt-4o", "claude-sonnet")
