    tokenBasedPricingSchema = z3.object({
      cost_calculation: z3.literal("token_based"),
      model: z3.string().optional(),
      input_cost_per_1k_tokens: z3.number().min(0),
      output_cost_per_1k_tokens: z3.number().min(0)
    });
    unitBasedPricingSchema = z3.object({
      cost_calculation: z3.literal("unit_based"),
      cost_per_unit: z3.number().min(0)
    });
    fixedCostPricingSchema = z3.object({
      cost_calculation: z3.literal("fixed_cost"),
      fixed_cost: z3.number().min(0)
    });
    pricingJsonSchema = z3.union([
      tokenBasedPricingSchema,
      unitBasedPricingSchema,
      fixedCostPricingSchema
    ]);
    insertApiProviderSchemaWithValidation = insertApiProviderSchema.extend({
      currencyCode: z3.literal("USD"),
      // Enforce USD-only for now
      pricingJson: pricingJsonSchema
    });
