    eventRepeatEnum = pgEnum2("event_repeat", ["none", "daily", "weekly", "monthly_date", "monthly_weekday"]);
    eventAttendeeTypeEnum = pgEnum2("event_attendee_type", ["user", "student", "classroom", "institute"]);
    eventInviteStatusEnum = pgEnum2("event_invite_status", ["pending", "accepted", "declined"]);
    calendarEvents = pgTable2("calendar_events", {
      id: varchar2("id").primaryKey().default(sql2`gen_random_uuid()`),
      title: text2("title").notNull(),
      description: text2("description"),
      startTime: timestamp2("start_time", { withTimezone: true }).notNull(),
      endTime: timestamp2("end_time", { withTimezone: true }).notNull(),
      allDay: boolean2("all_day").default(false).notNull(),
      // Recurrence
      repeatType: eventRepeatEnum("repeat_type").default("none").notNull(),
      repeatInterval: integer2("repeat_interval").default(1),
      // every N weeks (for weekly type)
      repeatDays: jsonb2("repeat_days").$type(),
      // 0=Sun..6=Sat for weekly repeats
      repeatMonthWeek: integer2("repeat_month_week"),
      // for monthly_weekday: 1=first, 2=second, 3=third, -1=last
      repeatEndDate: timestamp2("repeat_end_date", { withTimezone: true }),
      // when recurrence stops
      // Event-type association FKs. Exactly one of serviceId / instituteId / classroomId
      // should be set (or none, for a standard event). Type is derived from which is set.
      // Service events follow the cascade-delete pattern already established.
      serviceId: varchar2("service_id").references(() => services.id, { onDelete: "cascade" }),
      instituteId: varchar2("institute_id").references(() => institutes.id, { onDelete: "cascade" }),
      classroomId: varchar2("classroom_id").references(() => classrooms.id, { onDelete: "cascade" }),
      createdByUserId: varchar2("created_by_user_id").references(() => users.id).notNull(),
      createdAt: timestamp2("created_at", { withTimezone: true }).defaultNow().notNull(),
      updatedAt: timestamp2("updated_at", { withTimezone: true }).defaultNow().notNull()
    }, (table) => [
      index2("idx_calendar_events_start_time").on(table.startTime),
      index2("idx_calendar_events_end_time").on(table.endTime),
      index2("idx_calendar_events_created_by").on(table.createdByUserId),
      index2("idx_calendar_events_service_id").on(table.serviceId),
      index2("idx_calendar_events_institute_id").on(table.instituteId),
      index2("idx_calendar_events_classroom_id").on(table.classroomId)
    ]);
    calendarEventAttendees = pgTable2("calendar_event_attendees", {
      id: varchar2("id").primaryKey().default(sql2`gen_random_uuid()`),
      eventId: varchar2("event_id").references(() => calendarEvents.id, { onDelete: "cascade" }).notNull(),
      attendeeType: eventAttendeeTypeEnum("attendee_type").notNull(),
      attendeeId: varchar2("attendee_id").notNull(),
      // FK to users/students/classrooms/institutes
      inviteStatus: eventInviteStatusEnum("invite_status").default("pending").notNull(),
      createdAt: timestamp2("created_at", { withTimezone: true }).defaultNow().notNull()
    }, (table) => [
      index2("idx_event_attendees_event_id").on(table.eventId),
      index2("idx_event_attendees_type_id").on(table.attendeeType, table.attendeeId)
    ]);
    locations = pgTable2("locations", {
      id: varchar2("id").primaryKey().default(sql2`gen_random_uuid()`),
      instituteId: varchar2("institute_id").references(() => institutes.id, { onDelete: "cascade" }).notNull(),
      title: text2("title").notNull(),
      address: text2("address"),
      latitude: doublePrecision("latitude").notNull(),
      longitude: doublePrecision("longitude").notNull(),
      isActive: boolean2("is_active").default(true).notNull(),
      createdByUserId: varchar2("created_by_user_id").references(() => users.id).notNull(),
      createdAt: timestamp2("created_at", { withTimezone: true }).defaultNow().notNull(),
      updatedAt: timestamp2("updated_at", { withTimezone: true }).defaultNow().notNull()
    }, (table) => [
      index2("idx_locations_institute_id").on(table.instituteId),
      index2("idx_locations_lat_lng").on(table.latitude, table.longitude)
    ]);
    venues = pgTable2("venues", {
      id: varchar2("id").primaryKey().default(sql2`gen_random_uuid()`),
      // Where this record came from, and its id THERE. Together unique, so two
      // students near the same restaurant converge on one row.
      source: text2("source").notNull(),
      // 'osm' | 'brightdata' | 'manual'
      sourceId: text2("source_id").notNull(),
      name: text2("name").notNull(),
      latitude: doublePrecision("latitude").notNull(),
      longitude: doublePrecision("longitude").notNull(),
      address: text2("address"),
      // 'restaurant' | 'cafe' | 'fast_food' now; museum/cinema/clinic in phase 2.
      venueType: text2("venue_type"),
      cuisine: text2("cuisine"),
      // The place's OWN website, per-place rather than per-brand. Load-bearing for
      // the §3.1a binding check — it is what ties a scraped menu to THIS place.
      websiteUri: text2("website_uri"),
      // ISO-3166-1 alpha-2. The other half of the binding check: a `.ca` menu
      // against an `IL` venue is the Aroma defect, and is refused.
      countryCode: text2("country_code"),
      // Brand key for chain detection (`tommy-roll`). When several venues share
      // one, a menu bound only by brand is a `chain_fallback` and earns the §4.9
      // disclaimer rather than silent confidence.
      brandKey: text2("brand_key"),
      lastSeenAt: timestamp2("last_seen_at", { withTimezone: true }).defaultNow().notNull(),
      createdAt: timestamp2("created_at", { withTimezone: true }).defaultNow().notNull(),
      updatedAt: timestamp2("updated_at", { withTimezone: true }).defaultNow().notNull()
    }, (table) => [
      uniqueIndex2("idx_venues_source_source_id").on(table.source, table.sourceId),
      // Mirrors idx_locations_lat_lng — the nearby sweep is the hot query.
      index2("idx_venues_lat_lng").on(table.latitude, table.longitude),
      index2("idx_venues_brand_key").on(table.brandKey)
    ]);
    venueMenus = pgTable2("venue_menus", {
      id: varchar2("id").primaryKey().default(sql2`gen_random_uuid()`),
      venueId: varchar2("venue_id").references(() => venues.id, { onDelete: "cascade" }).notNull(),
      // The language the items are actually IN, so an RTL board lays out correctly.
      language: text2("language").default("en").notNull(),
      currency: text2("currency"),
      // Refined items: [{ name, description?, price?, priceText?, category?, kind,
      // imageKey?, translatedName? }] — post-applyMenuRefinement (§4.2a), so the
      // factual fields here are always the raw extraction's.
      items: jsonb2("items").default([]).notNull(),
      provenance: text2("provenance").notNull(),
      // 'camera' | 'web' | 'manual'
      sourceUrl: text2("source_url"),
      // ── Binding (§3.1a) ──
      // WHY we believe this menu belongs to this venue. NOT NULL by design: a menu
      // row cannot exist without recording its justification, which is what makes
      // the wrong-restaurant defect unrepresentable rather than merely unlikely.
      // 'gps_place_match' | 'place_website' | 'caretaker_confirmed' | 'camera'
      //                   | 'chain_fallback'
      bindingBasis: text2("binding_basis").notNull(),
      // The country the check compared against, stored so a later audit can re-run
      // the check over historical rows rather than trusting they were checked.
      bindingCountry: text2("binding_country"),
      // 'exact'   — the source names THIS branch
      // 'chain'   — right brand, different/unknown branch (the טומי רול defect)
      // 'unknown' — no branch signal in the source at all
      bindingBranchMatch: text2("binding_branch_match").default("unknown").notNull(),
      // ── Review (§4.8) ──
      status: text2("status").default("pending_review").notNull(),
      // 'pending_review' | 'approved' | 'rejected'
      extractedAt: timestamp2("extracted_at", { withTimezone: true }).defaultNow().notNull(),
      // Cross-schema FK: users.id lives in schema-private.ts.
      reviewedByUserId: varchar2("reviewed_by_user_id"),
      reviewedAt: timestamp2("reviewed_at", { withTimezone: true }),
      createdAt: timestamp2("created_at", { withTimezone: true }).defaultNow().notNull(),
      updatedAt: timestamp2("updated_at", { withTimezone: true }).defaultNow().notNull()
    }, (table) => [
      index2("idx_venue_menus_venue_id").on(table.venueId),
      // "Newest approved menu for this venue" is the read every session makes.
      index2("idx_venue_menus_venue_status").on(table.venueId, table.status),
      // A camera menu is the trust anchor; being able to find one cheaply matters.
      index2("idx_venue_menus_provenance").on(table.provenance)
    ]);
    calendarEventLocations = pgTable2("calendar_event_locations", {
      id: varchar2("id").primaryKey().default(sql2`gen_random_uuid()`),
      eventId: varchar2("event_id").references(() => calendarEvents.id, { onDelete: "cascade" }).notNull(),
      locationId: varchar2("location_id").references(() => locations.id, { onDelete: "cascade" }).notNull(),
      createdAt: timestamp2("created_at", { withTimezone: true }).defaultNow().notNull()
    }, (table) => [
      uniqueIndex2("idx_event_locations_event_location").on(table.eventId, table.locationId),
      index2("idx_event_locations_event_id").on(table.eventId),
      index2("idx_event_locations_location_id").on(table.locationId)
    ]);
