function normalizeAacPromptList(value) {
  if (value == null) return [];
  const arr = Array.isArray(value) ? value : [value];
  return arr.map((v) => typeof v === "string" ? v.trim() : "").filter((v) => v.length > 0);
}
function composeAacPersona(opts) {
  const custom = normalizeAacPromptList(opts.custom);
  const auto = normalizeAacPromptList(opts.auto);
  if (custom.length === 0 && auto.length === 0) return AAC_DEFAULT_PERSONA_PROMPT;
  const bullets = (items) => items.map((i) => `- ${i}`).join("\n");
  const parts = [];
  if (custom.length > 0) {
    parts.push(
      `Caretaker-requested behaviors \u2014 follow these. They take priority over the background notes below, except where they would conflict with safety:
${bullets(custom)}`
    );
  }
  if (auto.length > 0) {
    parts.push(`What to know about this student:
${bullets(auto)}`);
  }
  return parts.join("\n\n");
}
