function setupSocialBotWebSocket(server) {
  const wss2 = new WebSocketServer3({ noServer: true });
  server.on("upgrade", async (req, socket, head) => {
    const url = new URL(req.url || "", `http://${req.headers.host}`);
    if (url.pathname !== "/ws/social-bot") return;
    logLiveSession(
      "SOCIAL BOT UPGRADE",
      `incoming pathname=${url.pathname} host=${req.headers.host || ""}`
    );
    let user;
    try {
      user = await authenticateUpgrade(req);
    } catch (err) {
      logLiveSession("SOCIAL BOT UPGRADE", `authenticateUpgrade threw: ${err.message || err}`);
      socket.write("HTTP/1.1 500 Internal Server Error\r\n\r\n");
      socket.destroy();
      return;
    }
    if (!user) {
      logLiveSession("SOCIAL BOT UPGRADE", "401 \u2014 authenticateUpgrade returned null");
      socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n");
      socket.destroy();
      return;
    }
    wss2.handleUpgrade(req, socket, head, (ws) => {
      try {
        new SocialBotRelay(ws, user);
      } catch (err) {
        logLiveSession("SOCIAL BOT UPGRADE", `relay constructor threw: ${err.message || err}`);
        try {
          ws.close(1011, "relay init failed");
        } catch {
        }
      }
    });
  });
  console.log("[SocialBotRelay] WebSocket server ready on /ws/social-bot");
  logLiveSession("SOCIAL BOT STARTUP", "setupSocialBotWebSocket \u2014 upgrade listener attached on /ws/social-bot");
}

// server/services/realtime/realtime-server.ts
init_ws_auth();
init_room_registry();
import { WebSocketServer as WebSocketServer4 } from "ws";
