// server/services/call/turnCredentials.ts
import { createHmac as createHmac3 } from "crypto";
var DEFAULT_STUN = ["stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302"];
var DEFAULT_TTL_SECONDS = 3600;
function splitEnvList(value) {
  if (!value) return [];
  return value.split(",").map((s) => s.trim()).filter(Boolean);
}
function buildIceConfig(label, env2 = process.env, nowMs = Date.now()) {
  const stunUrls = splitEnvList(env2.STUN_URLS);
  const iceServers = [
    { urls: stunUrls.length > 0 ? stunUrls : DEFAULT_STUN }
  ];
  const turnUrls = splitEnvList(env2.TURN_URLS);
  const secret = env2.TURN_SECRET;
  if (turnUrls.length > 0 && secret) {
    const ttl = Number(env2.TURN_TTL) > 0 ? Number(env2.TURN_TTL) : DEFAULT_TTL_SECONDS;
    const expiry = Math.floor(nowMs / 1e3) + ttl;
    const safeLabel = (label || "anon").replace(/[^A-Za-z0-9_-]/g, "");
    const username = `${expiry}:${safeLabel}`;
    const credential = createHmac3("sha1", secret).update(username).digest("base64");
    iceServers.push({ urls: turnUrls, username, credential });
  }
  return { iceServers };
}

// server/services/call/clinician-stt.ts
init_google_stt_service();
init_dual_agent_logger();
var SESSION_MAX_MS = 4 * 60 * 1e3;
var GAP_RESET_MS = 8e3;
var ClinicianStt = class {
  constructor(languageHint, onFinal, sampleRate, onTranscript) {
    this.languageHint = languageHint;
    this.onFinal = onFinal;
    this.sampleRate = sampleRate;
    this.onTranscript = onTranscript;
    this.session = null;
    this.startedAt = 0;
    this.lastFeedAt = 0;
    this.chunkCount = 0;
    this.interimLogged = false;
  }
  /** Feed a base64 LINEAR16 chunk; lazily opens / rolls over the session. */
  feed(base64) {
    const now = Date.now();
    if (!this.session) {
      this.open();
    } else if (now - this.lastFeedAt > GAP_RESET_MS || now - this.startedAt > SESSION_MAX_MS) {
      this.rollover();
    }
    this.lastFeedAt = now;
    this.chunkCount++;
    if (this.chunkCount % 50 === 1) {
      logLiveSession("CLINICIAN_STT", `feeding audio \u2014 chunk #${this.chunkCount} (~${base64.length * 0.75 | 0} bytes), session=${this.session ? "open" : "none"}`);
    }
    this.session.write(base64);
  }
  open() {
    this.startedAt = Date.now();
    logLiveSession("CLINICIAN_STT", `opening Google STT streaming session (lang=${this.languageHint ?? "?"}, sampleRate=${this.sampleRate})`);
    const s = createStreamingSession({
      languageHint: this.languageHint,
      sampleRateHertz: this.sampleRate,
      model: "latest_short",
      // Interim results: lets us confirm the recognizer is hearing speech even
      // before a phrase is committed (diagnostic) and tends to commit finals
      // more reliably on a continuous stream.
      onInterim: (text3) => {
        if (!this.interimLogged && text3.trim()) {
          this.interimLogged = true;
          logLiveSession("CLINICIAN_STT", `STT interim (first): "${text3}" \u2014 recognizer is hearing audio`);
        }
        if (text3.trim()) this.onTranscript?.(text3, false);
      },
      onFinal: (text3) => {
        const t = text3.trim();
        if (!t) return;
        this.onTranscript?.(t, true);
        this.onFinal(t);
      },
      // On a terminal stream error, drop the session so the next chunk reopens.
      onError: (msg) => {
        console.warn("[clinicianStt]", msg);
        logLiveSession("CLINICIAN_STT", `STT stream ERROR: ${msg}`);
        if (this.session === s) this.session = null;
      }
    });
    this.session = s;
  }
  rollover() {
    const old = this.session;
    this.session = null;
    void old?.end().catch(() => {
    });
    this.open();
  }
  /** End the session (call ended / socket closed). */
  stop() {
    const old = this.session;
    this.session = null;
    void old?.end().catch(() => {
    });
  }
};

