var MULTIPLAYER_TYPES = [WORLD_APP_TYPE];
async function listSocialGameOptions(instituteId) {
  const options = [DEFAULT_SOCIAL_GAME, DOLLHOUSE_CALL_GAME, NATURE_HIKE_CALL_GAME];
  const apps = await customAppRepository.listMultiplayerAppsForInstitute(instituteId, MULTIPLAYER_TYPES);
  for (const app2 of apps) {
    const full = await customAppRepository.getApp(app2.id);
    if (!full) continue;
    const certified = certifyWorldSpec(full.definition);
    if (!certified.ok) continue;
    options.push({
      appId: app2.id,
      engine: WORLD_APP_TYPE,
      name: app2.name ?? certified.spec.meta.title,
      worldSpec: certified.spec,
      maxPlayers: certified.spec.multiplayer.maxPlayers
    });
  }
  return options;
}

