      if (actor?.id === id) {
        res.status(400).json({
          success: false,
          message: "You cannot delete your own admin account"
        });
        return;
      }
      const existing = await adminUserRepository.getById(id);
      if (!existing) {
        res.status(404).json({ success: false, message: "Admin not found" });
        return;
      }
      await adminUserRepository.delete(id);
