// server/controllers/interpretationController.ts
init_repositories();
import { z as z8 } from "zod";

// server/services/interpretationService.ts
init_storage();
init_apiTracker();
init_credit_ledger();
import { GoogleGenAI as GoogleGenAI12 } from "@google/genai";
var INTERPRETATION_MODEL = "gemini-2.5-pro";
function chargeInterpretationUsage(response, userId, label) {
  const usage = response?.usageMetadata;
  if (!usage) return;
  chargeModelUsage({
    provider: "gemini",
    model: INTERPRETATION_MODEL,
    promptTokens: usage.promptTokenCount ?? 0,
    completionTokens: (usage.candidatesTokenCount ?? 0) + (usage.thoughtsTokenCount ?? 0),
    cachedTokens: usage.cachedContentTokenCount ?? 0,
    userId,
    category: "interpretation",
    label
  }).catch((err) => console.error("[InterpretationService] cost ledger charge failed:", err));
}
var ai = new GoogleGenAI12({ apiKey: process.env.GEMINI_API_KEY || "" });
async function interpretAACText(input, language = "he", context, studentInfo, userId, sessionId) {
  try {
    const isHebrew = language === "he";
    const systemPromptTemplate = await storage.getSystemPrompt();
    const languagePrompt = language === "he" ? "Hebrew (\u05E2\u05D1\u05E8\u05D9\u05EA)" : "English";
    const contextInfo = context || "No additional context provided";
    const userInfo = studentInfo ? `Name: ${studentInfo.alias || "Unknown"}, Age: ${studentInfo.age || "Unknown"}, Background: ${studentInfo.backgroundContext || "No background info"}` : "No user profile available";
    const systemPrompt = systemPromptTemplate.replace("{input}", input).replace("{language}", languagePrompt).replace("{context}", contextInfo).replace("{studentInfo}", userInfo);
    const requestData = {
      model: INTERPRETATION_MODEL,
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: {
          type: "object",
          properties: {
            interpretedMeaning: { type: "string" },
            analysis: {
              type: "array",
              items: { type: "string" }
            },
            confidence: { type: "number" },
            suggestedResponse: { type: "string" }
          },
          required: ["interpretedMeaning", "analysis", "confidence", "suggestedResponse"]
        }
      },
      contents: isHebrew ? `\u05D0\u05E0\u05D0 \u05E4\u05E8\u05E9 \u05D0\u05EA \u05D4\u05EA\u05E7\u05E9\u05D5\u05E8\u05EA \u05D4\u05DE\u05E1\u05D9\u05D9\u05E2\u05EA \u05D4\u05D6\u05D5: "${input}"` : `Please interpret this AAC communication: "${input}"`
    };
    const response = await apiTracker.trackGeminiCall(
      async () => await ai.models.generateContent(requestData),
      "/v1beta/models/gemini-2.5-pro:generateContent",
      "gemini-2.5-pro",
      void 0,
      // inputTokens - will be extracted from response
      void 0,
      // outputTokens - will be extracted from response
      input.length,
      // estimatedTokens based on input length
      userId,
      sessionId
    );
    chargeInterpretationUsage(response, userId, "aac-interpretation-text");
    const rawJson = response.text;
    if (rawJson) {
      const result = JSON.parse(rawJson);
      return {
        interpretedMeaning: result.interpretedMeaning || "Unable to interpret",
        analysis: result.analysis || ["No analysis available"],
        confidence: Math.max(0, Math.min(1, result.confidence || 0)),
        suggestedResponse: result.suggestedResponse || "No suggestion available"
      };
    } else {
      throw new Error("Empty response from Gemini model");
    }
  } catch (error) {
    console.error("Gemini API error:", error);
    const errorMessage = error.message || "";
    if (errorMessage.includes("503") && errorMessage.includes("overloaded")) {
      throw new Error("MODEL_OVERLOADED");
    }
    throw new Error("Failed to interpret AAC communication: " + errorMessage);
  }
}
