import OpenAI4 from "openai";
var openai = new OpenAI4({
  apiKey: process.env.OPENAI_API_KEY
});
function getFileExtension(mimeType) {
  const mimeMap = {
    "audio/webm": "webm",
    "audio/webm;codecs=opus": "webm",
    "audio/mp3": "mp3",
    "audio/mpeg": "mp3",
    "audio/wav": "wav",
    "audio/wave": "wav",
    "audio/x-wav": "wav",
    "audio/m4a": "m4a",
    "audio/mp4": "m4a",
    "audio/x-m4a": "m4a",
    "audio/ogg": "ogg",
    "audio/ogg;codecs=opus": "ogg",
    "audio/flac": "flac"
  };
  const baseMime = mimeType.split(";")[0].trim();
  return mimeMap[baseMime] || mimeMap[mimeType] || "webm";
}
async function transcribe(audioBuffer, mimeType, options = {}) {
  const extension = getFileExtension(mimeType);
  const filename = `audio.${extension}`;
  const file = new File([audioBuffer], filename, { type: mimeType });
  console.log(`[WhisperService] Transcribing audio: ${audioBuffer.length} bytes, type: ${mimeType}`);
  const response = await openai.audio.transcriptions.create({
    file,
    model: "whisper-1",
    language: options.languageHint,
    // Optional: 'en', 'he', etc.
    response_format: "verbose_json",
    prompt: options.prompt
  });
  console.log(`[WhisperService] Transcription complete: "${response.text.substring(0, 100)}..." (lang: ${response.language})`);
  return {
    text: response.text,
    language: response.language || "en",
    duration: response.duration
  };
}
async function transcribeToText(audioBuffer, mimeType, languageHint) {
  const result = await transcribe(audioBuffer, mimeType, { languageHint });
  return result.text;
}
var whisperService = {
  transcribe,
  transcribeToText
};

