// server/lib/blob-cache.ts
import crypto13 from "crypto";
function blobETag(storageKey) {
  return `"${crypto13.createHash("sha256").update(storageKey).digest("hex").slice(0, 32)}"`;
}
function sendNotModified(req, res, storageKey) {
  const etag = blobETag(storageKey);
  res.setHeader("ETag", etag);
  res.setHeader("Cache-Control", "private, no-cache");
  const ifNoneMatch = req.headers["if-none-match"];
  if (!ifNoneMatch) return false;
  const tags = ifNoneMatch.split(",").map((t) => t.trim().replace(/^W\//, ""));
  if (!tags.includes(etag) && !tags.includes("*")) return false;
  res.status(304).end();
  return true;
}

