async function handleCallConversation(socket, personId, join6, callId) {
  logLiveSession("CHAT_ROOM", `/ws/call call:conversation join=${join6} callId=${callId} person=${personId}`);
  if (join6) {
    const actingPerson = await personRepository.getById(personId);
    if (actingPerson?.studentId) {
      logLiveSession("CHAT_ROOM", `/ws/call skipping room-join: person=${personId} is a STUDENT (studentId=${actingPerson.studentId}) \u2014 joins via dual-agent instead`);
      return;
    }
    if (socket.__convRoomId === callId) return;
    logLiveSession("CHAT_ROOM", `/ws/call CLINICIAN person=${personId} joining conversation room=${callId}`);
    const name = await personRepository.getDisplayName(personId);
    const roster = /* @__PURE__ */ new Map();
    const photoCache = /* @__PURE__ */ new Map();
    socket.__convRoomId = callId;
    socket.__convRoster = roster;
    const sendRoster = () => {
      if (socket.readyState !== socket.OPEN) return;
      socket.send(JSON.stringify({
        type: "call:roster",
        participants: Array.from(roster.entries()).map(([pid, n]) => ({ personId: pid, name: n, photo: photoCache.get(pid) }))
      }));
    };
    const ensureRosterPhotos = () => {
      const missing = Array.from(roster.keys()).filter((pid) => !photoCache.has(pid));
      if (missing.length === 0) return;
      void Promise.all(missing.map(async (pid) => {
        photoCache.set(pid, await getPeerFacePhotoDataUrl(pid) ?? void 0);
      })).then(() => sendRoster()).catch((err) => console.error("[call] roster photos:", err));
    };
    joinRoom(callId, {
      personId,
      name,
      onUtterance: () => {
      },
      onPresence: (p) => {
        if (p.joined) roster.set(p.personId, p.name);
        else roster.delete(p.personId);
        sendRoster();
        ensureRosterPhotos();
      },
      onRoster: (members) => {
        for (const m of members) roster.set(m.personId, m.name);
        sendRoster();
        ensureRosterPhotos();
      },
      onFloor: () => {
      },
      onPeerFocus: (f) => {
        if (f.targetPersonId !== personId || socket.readyState !== socket.OPEN) return;
        socket.send(JSON.stringify({ type: "call:addressed", fromPersonId: f.fromPersonId, fromName: f.fromName }));
      }
    });
  } else {
    const roomId = socket.__convRoomId;
    if (roomId) {
      leaveRoom(roomId, personId);
      socket.__convRoomId = null;
      socket.__convRoster = null;
    }
    socket.__stt?.stop();
    socket.__stt = null;
  }
}
