  app2.post("/api/students/:id/reload-aac", requireAuth, async (req, res) => {
    try {
      const user = req.user;
      const studentId = req.params.id;
      const access = await studentService.verifyStudentAccess(studentId, user.id);
      if (!access.hasAccess) {
        res.status(403).json({ success: false, message: "Forbidden" });
        return;
      }
      const session2 = getLiveSession(studentId);
      if (session2) session2.requestReload();
      res.json({ success: true, online: !!session2 });
    } catch (err) {
      res.status(500).json({ success: false, message: err?.message ?? "Failed to reload" });
    }
  });
