  app2.post("/api/aac/live/ws-ticket", requireAuth, async (req, res) => {
    try {
      const user = req.user;
      if (!user?.id) {
        res.status(401).json({ success: false, message: "Unauthorized" });
        return;
      }
      const { mintWsTicket: mintWsTicket2, TICKET_TTL_MS: TICKET_TTL_MS2 } = await Promise.resolve().then(() => (init_ws_ticket(), ws_ticket_exports));
      res.json({ success: true, ticket: mintWsTicket2(user.id), expiresInMs: TICKET_TTL_MS2 });
    } catch (err) {
      res.status(500).json({ success: false, message: err?.message ?? "Failed to mint ticket" });
    }
  });
