  app2.post("/api/aac/app-ai/select", optionalAuth, async (req, res) => {
    try {
      const { normalizeSelectRequest: normalizeSelectRequest2, selectFromOptions: selectFromOptions2, allowAppAiSelect: allowAppAiSelect2 } = await Promise.resolve().then(() => (init_appAiService(), appAiService_exports));
      const norm = normalizeSelectRequest2(req.body);
      if (!norm.ok) return res.status(400).json({ ok: false, error: norm.error });
      const userId = req.user?.id;
      const sessionId = typeof req.body?.sessionId === "string" ? req.body.sessionId : void 0;
      const limiterKey = userId || sessionId || req.ip || "anon";
      if (!allowAppAiSelect2(limiterKey)) {
        return res.status(429).json({ ok: false, error: "rate limited \u2014 too many selections" });
      }
      const result = await selectFromOptions2(norm.value, userId, sessionId);
      return res.json({ ok: true, ...result });
    } catch (err) {
      console.error("[routes] app-ai/select failed:", err?.message || err);
      return res.status(500).json({ ok: false, error: "selection failed" });
    }
  });
  app2.post("/api/aac/youtube/resolve-channel", requireAuth, async (req, res) => {
    try {
      const { input } = req.body || {};
      if (typeof input !== "string" || !input.trim()) {
        return res.status(400).json({ error: "input required" });
      }
      const { resolveChannelIdFromUrl: resolveChannelIdFromUrl2, fetchChannelMetadata: fetchChannelMetadata2 } = await Promise.resolve().then(() => (init_channel_search(), channel_search_exports));
      const channelId = await resolveChannelIdFromUrl2(input);
      if (!channelId) return res.status(404).json({ error: "Could not resolve channel ID from URL." });
      const metadata = await fetchChannelMetadata2(channelId);
      return res.json({
        channelId,
        title: metadata.title,
        description: metadata.description
      });
    } catch (err) {
      console.error("[routes] resolve-channel failed:", err?.message || err);
      return res.status(500).json({ error: "Resolver failed" });
    }
  });
