      if (typeof channelId !== "string" || !/^UC[A-Za-z0-9_-]{20,}$/.test(channelId)) {
        return res.status(400).json({ error: "valid channelId required" });
      }
      const { fetchChannelRssVideos: fetchChannelRssVideos2 } = await Promise.resolve().then(() => (init_channel_search(), channel_search_exports));
      const videos = await fetchChannelRssVideos2(channelId);
      return res.json({ channelId, videos });
