  app2.post("/api/aac/youtube/resolve", requireAuth, async (req, res) => {
    try {
      const { input } = req.body || {};
      if (typeof input !== "string" || !input.trim()) {
        return res.status(400).json({ error: "input required" });
      }
      const {
        resolveYoutubeItemFromUrl: resolveYoutubeItemFromUrl2,
        fetchChannelMetadata: fetchChannelMetadata2,
        fetchVideoMetadata: fetchVideoMetadata2,
        fetchPlaylistMetadata: fetchPlaylistMetadata2
      } = await Promise.resolve().then(() => (init_channel_search(), channel_search_exports));
      const resolved = await resolveYoutubeItemFromUrl2(input);
      if (!resolved) {
        return res.status(404).json({ error: "Could not recognize that YouTube URL or ID." });
      }
      let title = null;
      let description = null;
      let thumbnailUrl = null;
      if (resolved.type === "channel") {
        const m = await fetchChannelMetadata2(resolved.id);
        title = m.title;
        description = m.description;
      } else if (resolved.type === "video") {
        const m = await fetchVideoMetadata2(resolved.id);
        title = m.title;
        description = m.description;
        thumbnailUrl = m.thumbnailUrl;
      } else {
        const m = await fetchPlaylistMetadata2(resolved.id);
        title = m.title;
        description = m.description;
        thumbnailUrl = m.thumbnailUrl;
      }
      return res.json({ type: resolved.type, id: resolved.id, title, description, thumbnailUrl });
    } catch (err) {
      console.error("[routes] youtube resolve failed:", err?.message || err);
      return res.status(500).json({ error: "Resolver failed" });
    }
  });
  app2.get("/api/aac/youtube/embed", async (req, res) => {
    const videoId = req.query.v;
    console.log(
      "[youtube/embed] hit",
      JSON.stringify({
        v: typeof videoId === "string" ? videoId : typeof videoId,
        origin: req.headers.origin ?? null,
        referer: req.headers.referer ?? null,
        host: req.headers.host ?? null,
        ua: (req.headers["user-agent"] ?? "").slice(0, 80)
      })
    );
    try {
      const { renderYoutubeEmbedPage: renderYoutubeEmbedPage2, isValidYoutubeVideoId: isValidYoutubeVideoId2 } = await Promise.resolve().then(() => (init_youtube_embed_page(), youtube_embed_page_exports));
      if (!isValidYoutubeVideoId2(videoId)) {
        console.warn("[youtube/embed] rejected invalid videoId:", videoId);
        return res.status(400).type("html").send("<!DOCTYPE html><title>Invalid video</title>");
      }
      const devAncestors = process.env.NODE_ENV === "production" ? "" : " http://localhost:* http://127.0.0.1:*";
      res.removeHeader("X-Frame-Options");
      res.setHeader(
        "Content-Security-Policy",
        `frame-ancestors 'self' app: capacitor: https://localhost${devAncestors}`
      );
      res.setHeader("Cache-Control", "public, max-age=3600");
      const html = renderYoutubeEmbedPage2(videoId);
      console.log(`[youtube/embed] served ${videoId} (${html.length} bytes)`);
      return res.type("html").send(html);
    } catch (err) {
      console.error("[youtube/embed] FAILED for", videoId, "-", err?.stack || err?.message || err);
      return res.status(500).type("html").send("<!DOCTYPE html><title>Embed error</title>");
    }
  });
